import {saleKey,saleByKey,effectiveSale,correctionsFor} from './business-read.js';
import {correctionPreview} from './sale-corrections.js';
export function createCorrectionUI(env,workspace){
  const {state,esc,money,icon,btn,go,render,doc,formData,notify,accountName}=env;
  const d=()=>state.workspaceDraft;
  const original=()=>saleByKey(state,state.workspaceFocusId||state.saleId);
  const selectAccount=(name,v)=>`<label>Cuenta<select name="${name}">${['cash','brubank','mp','nx'].map(a=>`<option value="${a}" ${a===v?'selected':''}>${accountName(a)}</option>`).join('')}</select></label>`;
  const input=(label,name,v,attrs='')=>`<label>${label}<input class="customer-input" name="${name}" value="${esc(v??'')}" ${attrs}></label>`;
  const amt=(label,name,v)=>input(label,name,v,'type="number" min="1" max="999999999" step="1" inputmode="numeric" required');
  function choice(){const s=original();return `<p class="caption">Venta ${s.number} · ${money(effectiveSale(state,saleKey(s)).total)}. Conservás el registro original y agregás una corrección con sus efectos.</p>${[['commercial','Cantidad, producto o precio','Revisar el importe comercial y sus efectos'],['account','Cuenta del cobro','Corregir dónde se registró un cobro confirmado'],['money','Cobro adicional o devolución','Registrar dinero que efectivamente entró o salió']].map(([type,title,desc])=>`<button class="menu-row" data-correction="type" data-type="${type}">${icon('edit')}<span class="grow"><strong>${title}</strong><span class="meta">${desc}</span></span>${icon('chevron')}</button>`).join('')}`;}
  function begin(type){const s=effectiveSale(state,saleKey(original()));workspace.start('sale-correction',{saleId:s.originalId,expectedRevision:s.revision,type,reason:'',lines:s.items.map(i=>({id:i.id,qty:String(i.qty),price:String(i.price)})),discount:String(s.discount),settlement:'paid',account:'cash',partId:s.parts.find(p=>p.verified)?.id||'',direction:'collect',amount:'',customer:state.debts.find(v=>v.saleId===s.originalId)?.customer||s.customer,occurredConfirmed:false},'correctionForm',s.originalId);}
  function form(){const v=d(),s=effectiveSale(state,v.saleId);return `<p class="caption">Venta ${s.number}. El motivo y los efectos quedan en el historial.</p><form id="correction-form" class="product-form workflow-form">${v.type==='commercial'?`${v.lines.map((i,n)=>`<section class="workflow-section"><label>Producto<select name="product_${n}">${state.products.map(p=>`<option value="${p.id}" ${p.id===i.id?'selected':''}>${esc(p.name+' · '+p.variety+' · '+p.size)}</option>`).join('')}</select></label>${amt('Unidades','qty_'+n,i.qty)}${amt('Precio unitario ($)','price_'+n,i.price)}${v.lines.length>1?`<button type="button" class="text-btn" data-correction="remove" data-index="${n}">Quitar producto</button>`:''}</section>`).join('')}<button type="button" class="text-btn" data-correction="add">${icon('plus')}Agregar producto</button>${input('Descuento total ($)','discount',v.discount,'type="number" min="0" step="1" required')}<label>Si cambia el total<select name="settlement"><option value="paid" ${v.settlement==='paid'?'selected':''}>La diferencia ya fue cobrada o devuelta</option><option value="debt" ${v.settlement==='debt'?'selected':''}>La diferencia modifica el fiado</option></select></label>${v.settlement==='debt'?input('Cliente del fiado','customer',v.customer,'maxlength="80"'):selectAccount('account',v.account)}`:v.type==='account'?`<label>Cobro confirmado a corregir<select name="partId">${s.parts.filter(p=>p.verified).map(p=>`<option value="${p.id}" ${v.partId===p.id?'selected':''}>${accountName(p.account)} · ${money(p.amount)}</option>`).join('')}</select></label>${selectAccount('account',v.account)}<p class="caption">Compensa la atribución de cuenta. No registra otro cobro ni un traspaso real.</p>`:`<label>Qué ocurrió<select name="direction"><option value="collect" ${v.direction==='collect'?'selected':''}>Cobro adicional recibido</option><option value="refund" ${v.direction==='refund'?'selected':''}>Devolución entregada</option></select></label>${amt('Importe real ($)','amount',v.amount)}${selectAccount('account',v.account)}<p class="caption">Esto cambia el dinero registrado. El importe comercial y los productos de la venta se conservan.</p>`}${input('Motivo de la corrección','reason',v.reason,'required maxlength="300"')}${v.type!=='commercial'||v.settlement==='paid'?`<label class="workflow-check"><input type="checkbox" name="occurredConfirmed" ${v.occurredConfirmed?'checked':''}>Comprobé la cuenta y el cobro o devolución real que estoy registrando</label>`:''}<p id="correction-error" class="error" role="alert"></p></form>`;}
  function capture(){const f=doc.querySelector('#correction-form'),v=d();if(!f||!v)return;const fd=formData(f);for(const key of ['reason','discount','settlement','customer','account','partId','direction','amount'])if(fd.has(key))v[key]=String(fd.get(key));v.occurredConfirmed=fd.has('occurredConfirmed');if(v.type==='commercial')v.lines=v.lines.map((i,n)=>({id:String(fd.get('product_'+n)),qty:String(fd.get('qty_'+n)),price:String(fd.get('price_'+n))}));}
  function payload(){const v=d();return {saleId:v.saleId,expectedRevision:v.expectedRevision,type:v.type,reason:v.reason,...(v.type==='commercial'?{items:v.lines.map(i=>({id:i.id,qty:Number(i.qty),price:Number(i.price)})),discount:Number(v.discount),settlement:v.settlement,customer:v.customer}:v.type==='account'?{partId:v.partId}:{amount:Number(v.amount),direction:v.direction}),account:v.account,occurredConfirmed:!!v.occurredConfirmed};}
  function effects(c){if(c.status==='review')return `<p class="supplier-issue">Requiere revisión: ${esc(c.message)}</p><p class="caption">No se modificó stock, venta, deuda ni dinero.</p>`;return `<dl class="workflow-summary"><div><dt>Total anterior</dt><dd>${money(c.before.total)}</dd></div><div><dt>Total corregido</dt><dd>${money(c.after.total)}</dd></div><div><dt>${c.moneyDelta===0?'Sin cambios en el dinero cobrado':'Cambio en el dinero cobrado'}</dt><dd>${c.moneyDelta===0?'—':(c.moneyDelta>0?'+':'')+money(c.moneyDelta)}</dd></div><div><dt>Cambio del fiado</dt><dd>${c.debtDelta>0?'+':''}${money(c.debtDelta)}</dd></div></dl>${c.stockEffects.length?c.stockEffects.map(x=>`<p class="caption">${esc(state.products.find(p=>p.id===x.productId)?.name)} · stock ${x.delta>0?'+':''}${x.delta} un.</p>`).join(''):'<p class="caption">Sin cambio de existencias.</p>'}${c.accountEffect?`<p class="caption">Cuenta: ${accountName(c.accountEffect.from)} → ${accountName(c.accountEffect.to)} · ${money(c.accountEffect.amount)}. Sin dinero nuevo.</p>`:''}`;}
  function review(){const c=correctionPreview(state,payload());return `<h2 class="section-title">${c.status==='review'?'Guardar para revisar':'Confirmá estos efectos'}</h2>${effects(c)}<p class="caption">Motivo: ${esc(d().reason)}</p><p class="caption">La venta original y su costo histórico se conservan. Las devoluciones físicas ingresan como lotes nuevos con su costo original.</p>`;}
  function detail(){const c=state.saleCorrections.find(v=>v.id===state.workspaceFocusId);if(!c)return '<p>Corrección no disponible.</p>';return `<p class="available">${c.status==='applied'?'Corrección aplicada':'Corrección pendiente de revisión'}</p>${effects(c)}<p class="caption">${esc(c.reason)} · ${c.day}</p><button class="text-btn" data-correction="sale" data-sale-id="${c.saleId}">Ver venta de origen${icon('chevron')}</button>`;}
  function history(s){const cs=state.saleCorrections.filter(c=>c.saleId===saleKey(s));return `<div class="workflow-actions"><button class="btn secondary" data-correction="open" data-sale-id="${saleKey(s)}">${icon('edit')}Corregir venta</button></div>${cs.map(c=>`<button class="menu-row" data-correction="detail" data-id="${c.id}"><span class="grow"><strong>${c.status==='applied'?'Corrección aplicada':'Requiere revisión'}</strong><span class="meta">${esc(c.reason)} · ${c.day}</span></span>${icon('chevron')}</button>`).join('')}`;}
  function save(){capture();const f=doc.querySelector('#correction-form');if(f&&!f.reportValidity())return;try{if(state.page==='correctionForm'){correctionPreview(state,payload());go('correctionReview');}else workspace.run('sale-correction',payload());}catch(error){const el=doc.querySelector('#correction-error');if(el)el.textContent=error.message;else notify(error.message);}}
  function click(b){const action=b.dataset.correction;if(!action)return false;if(action==='open'){state.workspaceFocusId=b.dataset.saleId;go('correctionChoice');}if(action==='type')begin(b.dataset.type);if(action==='save')save();if(action==='add'){capture();const p=state.products.find(p=>!d().lines.some(i=>i.id===p.id));if(p)d().lines.push({id:p.id,qty:'1',price:String(p.price)});else notify('Los productos ya están incluidos.');render();}if(action==='remove'){capture();d().lines.splice(Number(b.dataset.index),1);render();}if(action==='detail'){state.workspaceFocusId=b.dataset.id;go('correctionDetail');}if(action==='sale'){state.saleId=saleByKey(state,b.dataset.saleId).number;go('saleDetail');}return true;}
  function onInput(e){if(e.target.closest?.('#correction-form'))capture();}
  function onChange(e){if(e.target.closest?.('#correction-form')){capture();if(e.target.name==='settlement')render();}}
  function dock(){return ['correctionForm','correctionReview'].includes(state.page)?`<div class="dock"><button class="btn primary" data-correction="save">${state.page==='correctionForm'?'Revisar efectos':'Confirmar corrección'}</button></div>`:'';}
  return {screens:{correctionChoice:choice,correctionForm:form,correctionReview:review,correctionDetail:detail},click,onInput,onChange,save,dock,history};
}
